; void blit_image(uint8_t *dst, const uint8_t *src, uint16_t plane, uint16_t shift, uint16_t rows), orig $0171E4:
; draw an image one word wide (the planes are `plane` bytes apart) through a mask built from its planes
_blit_image:
        movem.l d2-d7/a2-a4,-(sp)
        movea.l 40(sp),a0          ; dst
        movea.l 44(sp),a1          ; src
        move.w 50(sp),d0           ; bytes between the planes
        move.w 54(sp),d1           ; pixel shift
        move.w 58(sp),d7           ; rows
        move.l #$ffff,d3
        clr.w (Addr_blit_extra_modulo).w
        moveq #$1,d6
        moveq #$0,d2
        move.b d1,d2
        bra.b blit_image_body

; void blit_image_wide(...), orig $0171F6: the same for an image two words wide
_blit_image_wide:
        movem.l d2-d7/a2-a4,-(sp)
        movea.l 40(sp),a0          ; dst
        movea.l 44(sp),a1          ; src
        move.w 50(sp),d0           ; bytes between the planes
        move.w 54(sp),d1           ; pixel shift
        move.w 58(sp),d7           ; rows
        move.l #$ffff,d3
        clr.w (Addr_blit_extra_modulo).w
        move.w #$2,d6
        moveq #$0,d2
        move.b d1,d2
