        movea.l a1,a4
        movea.l (Addr_mask_buffer).w,a2
        lea.l $dff000.l,a3
        moveq #$0,d4
        moveq #$6,d5
        move.w d7,d4
        lsl.w d5,d4
        or.w d6,d4
